export type YoutubeJobStatus = "queued" | "running" | "succeeded" | "failed" | "cancelled";
export interface CreateYoutubeJob { requestId: string; chatId: string; userId: string; logId: string; url: string; }
export interface YoutubeJob extends CreateYoutubeJob { id: string; sequence: number; status: YoutubeJobStatus; createdAt: number; updatedAt: number; finishedAt?: number; errorCode?: string; artifactPath?: string; artifactBytes?: number; artifactSha256?: string; }
export function publicJob(job: YoutubeJob): Record<string, unknown> { return { jobId: job.id, requestId: job.requestId, chatId: job.chatId, status: job.status, queueSequence: job.sequence, createdAt: job.createdAt, updatedAt: job.updatedAt, error: job.errorCode ? { code: job.errorCode } : undefined, file: job.status === "succeeded" && job.artifactBytes !== undefined ? { mediaType: "video/mp4", bytes: job.artifactBytes, sha256: job.artifactSha256, href: `/v1/youtube/jobs/${job.id}/file?chatId=${job.chatId}` } : undefined }; }
